t2.value19 = loadstring(EMBED_UILIB)()
t2.value20 = t2.value19.newNotify()
t2.value21 = {
    _req_01 = function(_, _, _, cb) if cb then cb(true, { success = true, session_token = "", key_type = "Lifetime", keyType = "Lifetime", _validationProof = "" }) end end,
    _sec_02 = function() return true end,
    _sec_03 = function() return true, "Lifetime", {} end,
    _io_r = function() return "" end,
    _io_w = function() end,
    _io_d = function() end,
    _sys_id = function() return "unknown" end,
    _exec = function(cb) if cb then cb({ success = true, session_token = "", key_type = "Lifetime" }) end return true end,
    _token = function() return "" end,
    _type = function() return "Cracked" end
}
t2.value8 = {}
function t2.value8:Notify(opts)
    opts = opts or {}
    pcall(function()
        local t = tostring(opts.Title or "")
        local c = tostring(opts.Content or "")
        if t == "" then print("[WereTools] " .. c) else print("[WereTools] " .. t .. ": " .. c) end
    end)
    pcall(function()
        if t2.value20 and t2.value20.Notify then
            t2.value20:Notify(opts)
        end
    end)
end
local liveModules, livePayload, liveToken = nil, nil, nil
do
    local okA, authMod = pcall(function()
        return loadstring(game:HttpGet(LIVE_AUTH_URL))()
    end)
    if okA and type(authMod) == "table" then
        local okH, hwid = pcall(authMod._sys_id)
        if okH then
            local done, sess = nil, nil
            authMod._req_01(LIVE_KEY, hwid, game.PlaceId, function(s, data)
                local proof = s and data and data._validationProof
                if proof and authMod._sec_02(data._validationProof) then
                    sess = data.session_token
                    done = true
                else
                    done = false
                end
            end)
            local n = 0
            while done == nil and n < 100 do
                task.wait(0.1)
                n += 1
            end
            if done == true and sess and sess ~= "" then
                local okM, resM = pcall(function()
                    return game:HttpGet("https://weretools.xyz/api/v1/get-all-modules?token=" .. t2.value1:UrlEncode(sess) .. "&place_id=" .. t2.value7)
                end)
                if okM and resM and resM ~= "" and resM:sub(1, 1) == "{" then
                    local okJ, doc = pcall(function()
                        return t2.value1:JSONDecode(resM)
                    end)
                    if okJ and doc and doc.success and type(doc.modules) == "table" then
                        liveModules = doc.modules
                    end
                end
                if liveModules then
                    local okP, resP = pcall(function()
                        return game:HttpGet("https://weretools.xyz/api/v1/get-payload?token=" .. t2.value1:UrlEncode(sess) .. "&place_id=" .. t2.value7)
                    end)
                    if okP and resP and resP ~= "" and resP:sub(1, 1) ~= "{" then
                        livePayload = resP
                        liveToken = sess
                    else
                        liveModules = nil
                    end
                end
            end
        end
    end
end
local useModules = liveModules or EMBED_MODULES
local usePayload = livePayload or EMBED_PAYLOAD
local compiled = {}
for k, v in pairs(useModules) do
    local ok2, res2 = pcall(function() return loadstring(v)() end)
    if ok2 then compiled[k] = res2 end
end
_G.WereToolsModules = compiled
_G.WereToolsSessionToken = liveToken or ""
_G.Compkiller = t2.value19
_G.Notifier = t2.value20
_G.auth = t2.value21
if getgenv then
    getgenv().Compkiller = t2.value19
    getgenv().WereToolsModules = compiled
    getgenv().auth = t2.value21
end
local okp, errp = pcall(function() loadstring(usePayload)() end)
if okp then
    t2.value8:Notify({ Title = "", Content = LOAD_MSG, Duration = 4, Icon = t2.value12 })
else
    t2.value8:Notify({ Title = "Error", Content = "Payload crashed: " .. tostring(errp), Duration = 8 })
end
